/**
 * Modals focus the user’s attention on a single task in a window that sits on top of the page content.
 *
 * - {@link https://livingdesign.walmart.com/components/modal/ Guidelines}
 * - {@link https://livingdesign.walmart.com/components/modal/react/ React documentation}
 *
 * ### Content
 *
 * #### Children
 *
 * The Modal accepts valid React content through the `children` prop:
 *
 * ```tsx
 * <Modal
 *   onClose={() => setIsOpen(false)}
 *   title="Title"
 * >
 *   Content
 * </Modal>
 * ```
 *
 * #### Title
 *
 * The Modal requires a title which can be provided through the `title` prop:
 *
 * ```tsx
 * <Modal
 *   onClose={() => setIsOpen(false)}
 *   title="Title"
 * >
 *   Modal
 * </Modal>
 * ```
 *
 * #### Actions
 *
 * The Modal accepts a group of one or more button-like components through the optional `actions` prop:
 *
 * ```tsx
 * <Modal
 *   actions={
 *     <ButtonGroup>
 *       <Button>Action1</Button>
 *       <Button>Action2</Button>
 *     </ButtonGroup>
 *   }
 *   onClose={() => setIsOpen(false)}
 *   title="Title"
 * >
 *   Content
 * </Modal>
 * ```
 *
 * ### Opening and closing
 *
 * The Modal is set to open or close based on the `isOpen` prop. Provide a callback handler that manages the `isOpen` state through the `onClose` prop:
 *
 * ```tsx
 * export default () => {
 *   const [isOpen, setIsOpen] = React.useState(false);
 *
 *   return (
 *     <>
 *       <Button onClick={() => setIsOpen(true)}>
 *         Open modal
 *       </Button>
 *
 *       <Modal
 *         isOpen={isOpen}
 *         onClose={() => setIsOpen(false)}
 *         title="Title"
 *       >
 *         Content
 *       </Modal>
 *     </>
 *   );
 * };
 * ```
 *
 * #### Click Outside to Close
 *
 * By default, the modal will close when clicking outside of it. This behavior can be disabled by setting `closeOnOutsideClick` to `false`:
 *
 * ```tsx
 * <Modal
 *   isOpen={isOpen}
 *   onClose={() => setIsOpen(false)}
 *   title="Title"
 *   closeOnOutsideClick={false}
 * >
 *   This modal won't close when clicking outside
 * </Modal>
 * ```
 *
 * ### Features
 *
 * #### Size
 *
 * The Modal comes in four sizes:
 *
 * - `small` (default)
 * - `medium`
 * - `large`
 * - `mega`
 *
 * Set the size with the `size` prop:
 *
 * ```tsx
 * <Modal
 *   onClose={() => setIsOpen(false)}
 *   size="small"
 *   title="Title"
 * >
 *   Small
 * </Modal>
 *
 * <Modal
 *   onClose={() => setIsOpen(false)}
 *   size="medium"
 *   title="Title"
 * >
 *   Medium
 * </Modal>
 *
 * <Modal
 *   onClose={() => setIsOpen(false)}
 *   size="large"
 *   title="Title"
 * >
 *   Large
 * </Modal>
 * <Modal
 *   onClose={() => setIsOpen(false)}
 *   size="mega"
 *   title="Title"
 * >
 *   Mega
 * </Modal>
 * ```
 */
export declare const Modal: React.FunctionComponent<ModalProps>;
